/**
 *
 * AutoCompleteClear is the clear button for the AutoComplete component.
 *
 * [Live Demo](https://www.primereact.org/autocomplete/)
 *
 * @module AutoCompleteClear
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { AutoCompleteRootInstance } from './AutoCompleteRoot.types';
/**
 * Defines passthrough(pt) options type in AutoCompleteClear component.
 */
export type AutoCompleteClearPassThroughType<E> = PassThroughType<AutoCompleteClearInstance, E>;
/**
 * Defines passthrough(pt) options of AutoCompleteClear component.
 */
export interface AutoCompleteClearPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: AutoCompleteClearPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in AutoCompleteClear component.
 */
export interface AutoCompleteClearProps extends BaseComponentProps<AutoCompleteClearInstance, unknown, AutoCompleteClearPassThrough> {
}
/**
 * Defines valid state in AutoCompleteClear component.
 */
export interface AutoCompleteClearState {
}
/**
 * Defines the methods and properties exposed by AutoCompleteClear component.
 */
export interface AutoCompleteClearExposes {
    /**
     * The AutoComplete component instance.
     */
    autocomplete: AutoCompleteRootInstance | undefined | null;
}
/**
 * Instance of AutoCompleteClear component.
 */
export type AutoCompleteClearInstance = ComponentInstance<AutoCompleteClearProps, AutoCompleteClearState, AutoCompleteClearExposes>;
